async function visitLedger(stream, visitor) {
  const reader = stream.getReader();
  const carriageReturn = new Uint8Array([0x0d]);

  let accepted = 0;
  let rejected = 0;
  let line = 1;
  let cancelled = false;
  let decoder = makeDecoder();
  let pieces = [];
  let pendingCarriageReturn = false;

  function makeDecoder() {
    return new TextDecoder("utf-8", { ignoreBOM: true });
  }

  function writeBytes(bytes) {
    if (bytes.length === 0) return;
    const piece = decoder.decode(bytes, { stream: true });
    if (piece !== "") pieces.push(piece);
  }

  function appendBytes(bytes, start, end) {
    if (start >= end) return;

    if (pendingCarriageReturn) {
      writeBytes(carriageReturn);
      pendingCarriageReturn = false;
    }

    if (bytes[end - 1] === 0x0d) {
      if (end - start > 1) {
        writeBytes(bytes.subarray(start, end - 1));
      }
      pendingCarriageReturn = true;
    } else {
      writeBytes(bytes.subarray(start, end));
    }
  }

  function takeLine(atEof) {
    if (atEof && pendingCarriageReturn) {
      writeBytes(carriageReturn);
    }
    pendingCarriageReturn = false;

    const tail = decoder.decode();
    if (tail !== "") pieces.push(tail);

    const text = pieces.join("");
    pieces = [];
    decoder = makeDecoder();
    return text;
  }

  async function handleLine(atEof) {
    let text = takeLine(atEof);

    if (text.trim() === "") return false;

    let value;
    try {
      value = JSON.parse(text);
    } catch {
      rejected += 1;
      return false;
    }

    accepted += 1;
    text = "";

    return (await visitor({ line, value })) === false;
  }

  async function cancelOnce() {
    if (!cancelled) {
      cancelled = true;
      await reader.cancel();
    }
  }

  try {
    for (;;) {
      const result = await reader.read();

      if (result.done) {
        if (await handleLine(true)) {
          await cancelOnce();
          return { accepted, rejected, stopped: true };
        }
        return { accepted, rejected, stopped: false };
      }

      const bytes = result.value;
      let start = 0;

      for (let index = 0; index < bytes.length; index += 1) {
        if (bytes[index] !== 0x0a) continue;

        appendBytes(bytes, start, index);

        const stopped = await handleLine(false);
        line += 1;

        if (stopped) {
          await cancelOnce();
          return { accepted, rejected, stopped: true };
        }

        start = index + 1;
      }

      appendBytes(bytes, start, bytes.length);
    }
  } catch (error) {
    await cancelOnce();
    throw error;
  } finally {
    reader.releaseLock();
  }
}
